import { describe, it } from "vitest";

// Premium expectations include the always-applied 10 % first-insurance surcharge
// on the policy base premium and the 5 G processing fee, rounded up.
describe("claim office scenario", () => {
  describe("quote -- base premiums", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
    it.todo("newcomer, plain sword (base 100) -> premium 115 G (100 + 10 first insurance + 5 fee)");
    it.todo("newcomer, plain amulet (base 60) -> premium 71 G (60 + 6 + 5)");
    it.todo("newcomer, plain staff (base 80) -> premium 93 G (80 + 8 + 5)");
    it.todo("newcomer, plain potion (base 40) -> premium 49 G (40 + 4 + 5)");
    it.todo("newcomer, 1 rune (base 25) -> 32.5 rounded up in MHPCO's favor -> premium 33 G");
    it.todo("newcomer, 1 moonstone (base 25) -> premium 33 G");
    it.todo("newcomer, 2 runes (base 50) -> premium 60 G (50 + 5 + 5)");
    it.todo("newcomer, 3 runes form a block (base 60) -> premium 71 G (60 + 6 + 5)");
    it.todo("newcomer, 4 runes, no block (base 100) -> premium 115 G");
    it.todo("newcomer, 7 runes, no block (base 175) -> 197.5 rounded up -> premium 198 G");
    it.todo("newcomer, 2 runes + 1 moonstone, no block across types (base 75) -> 87.5 rounded up -> premium 88 G");
    it.todo("newcomer, 3 runes + 3 moonstones form two blocks (base 120) -> premium 137 G (120 + 12 + 5)");
  });

  describe("quote -- premium modifiers", () => {
    it.todo("newcomer, cursed sword enchantment 3 -> premium 165 G (100 + 50 curse + 10 + 5)");
    it.todo("newcomer, sword with exactly enchantment 5 -> high-enchantment surcharge applies -> premium 145 G (100 + 30 + 10 + 5)");
    it.todo("newcomer, sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
    it.todo("newcomer, cursed sword with enchantment 5 -> both surcharges -> premium 195 G (100 + 50 + 30 + 10 + 5)");
    it.todo("newcomer, cursed sword with enchantment 4 -> only curse surcharge -> premium 165 G");
    it.todo("newcomer, cursed sword + plain amulet -> curse applies to the sword only -> premium 231 G (160 + 50 + 16 + 5)");
    it.todo("customer with exactly 2 years, plain sword -> loyalty discount applies -> premium 95 G (100 - 20 + 10 + 5)");
    it.todo("customer with 1 year, plain sword -> no loyalty discount -> premium 115 G");
    it.todo("newcomer's second quote, plain sword -> follow-up discount -> premium 100 G (100 + 10 - 15 + 5)");
    it.todo("3-year customer's second quote, cursed sword enchantment 7 -> first insurance still applies -> premium 160 G");
  });

  describe("claim -- payouts", () => {
    it.todo("steel sword enchantment 3, damage 500 -> payout 400 G, remaining cap 1600 G");
    it.todo("rune, damage 200 -> payout 100 G, remaining cap 400 G");
    it.todo("steel sword enchantment 9, damage 1000 -> 50 % then deductible -> payout 400 G");
    it.todo("dragon sword with exactly enchantment 8, damage 1000 -> payout 400 G");
    it.todo("dragon sword enchantment 9, damage 1000 -> 50 % rule wins -> payout 400 G");
    it.todo("dragon sword enchantment 5, damage 800 -> full reimbursement -> payout 700 G");
    it.todo("sword (500) and amulet (300) damaged -> deductible per damaged item -> payout 600 G, remaining cap 2600 G");
    it.todo("two swords insured, both damaged 500 each -> payout 800 G, remaining cap 3200 G (cap 4000)");
    it.todo("sword enchantment 9, damage 901 -> 350.5 rounded down -> payout 350 G");
  });

  describe("claim -- cap", () => {
    it.todo("sword insured, two successive claims of 1500 -> payouts 1400 G then 600 G, remaining caps 600 G then 0 G");
    it.todo("cursed sword, damage 5000 -> cap 2000 G from unmodified insurance value -> payout 2000 G, remaining cap 0 G");
    it.todo("sword and amulet, damages 5000 each -> cap 3200 G -> payout 3200 G, remaining cap 0 G");
    it.todo("sword and 3 runes (block), sword damage 5000 -> cap 3500 G -> payout 3500 G, remaining cap 0 G");
    it.todo("staff, damage 200 -> remaining cap 1500 G (cap 1600)");
    it.todo("potion, damage 200 -> remaining cap 700 G (cap 800)");
    it.todo("moonstone, damage 200 -> remaining cap 400 G (cap 500)");
  });

  describe("rejections (thrown Error, whole scenario rejected)", () => {
    it.todo("quote with unknown item type broomstick -> throws Error");
    it.todo("claim damaging an amulet when only a sword is insured -> throws Error");
    it.todo("claim damaging an item of unknown type -> throws Error");
    it.todo("claim with two sword damages when only one sword is insured -> throws Error");
    it.todo("claim with damage amount -200 -> throws Error");
  });
});

