content.content:
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

const COMPONENT_BASE_PREMIUM = 25;

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const PRICE_LIST_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const HUNDRED_PERCENT = 100;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / HUNDRED_PERCENT;
}

function itemBasePremium(item: Item): number {
  return PRICE_LIST_BASE_PREMIUMS[item.type];
}

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function alikeComponentsBasePremium(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function componentCountsByType(components: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const component of components) {
    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
  }
  return counts;
}

function componentsBasePremium(components: Item[]): number {
  const alikeCounts = [...componentCountsByType(components).values()];
  return alikeCounts.reduce((sum, count) => sum + alikeComponentsBasePremium(count), 0);
}

function mainItemsBasePremium(mainItems: Item[]): number {
  return mainItems.reduce((sum, item) => sum + itemBasePremium(item), 0);
}

function policyBasePremium(items: Item[]): number {
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);
  return mainItemsBasePremium(mainItems) + componentsBasePremium(components);
}

function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
  return Math.ceil(premium);
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}

