const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_MIN_YEARS = 2;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
function loyaltyDiscountPercent(customer: Customer): number {
  return customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
}

function policyModifierPercent(customer: Customer): number {
  return FIRST_INSURANCE_SURCHARGE_PERCENT - loyaltyDiscountPercent(customer);
}

function quotePremium(customer: Customer, items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const riskSurcharge = policyRiskSurcharge(items);
  const policyModifier = percentOf(basePremium, policyModifierPercent(customer));
  const premium = basePremium + riskSurcharge + policyModifier + PROCESSING_FEE;
  return Math.ceil(premium);
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(scenario.customer, step.items) })) };
}

