import { quotePremium } from "./quotePremium";

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

function isFollowUpContract(contractIndex: number): boolean {
  return contractIndex > 0;
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  const results = scenario.steps.map((step, contractIndex) => ({
    premium: quotePremium(scenario.customer, step.items, isFollowUpContract(contractIndex)),
  }));
  return { results };
}
import type { Customer, Item } from "./claimOffice";

