import type { Damage, Item } from "./claimOffice";

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
};

export function payoutCap(items: Item[]): number {
  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
  return insuranceSum * CAP_MULTIPLIER;
}

export function claimPayout(damages: Damage[], remainingCap: number): number {
  const desiredPayout = damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE_PER_DAMAGE, 0);
  return Math.floor(Math.min(desiredPayout, remainingCap));
}
